const trailingWords = new Set(["dan", "atau", "untuk", "dengan", "dari", "di", "ke", "yang", "bersama"]);

function summarizeArticleTopic(title: string, category: string) {
  const topic = title
    .replace(/\s*[:|–—]\s*.*$/, "")
    .replace(/\?\s+.*$/, "")
    .replace(/\b(?:bersama|dari|ala|di)\s+indo\s*fish\s*mart\b/gi, "")
    .replace(/\bindo\s*fish\s*mart\b/gi, "")
    .replace(/[!?.,;]+$/g, "")
    .replace(/\s+/g, " ")
    .trim();

  const words = topic.split(" ").filter(Boolean).slice(0, 10);
  while (words.length > 1 && trailingWords.has(words.at(-1)?.toLowerCase() ?? "")) {
    words.pop();
  }

  return words.join(" ") || category || "produk frozen food";
}

function getEditorialContext(article: Pick<ArticleRecord, "slug" | "title" | "category">) {
  const subject = (article.slug + " " + article.title).toLowerCase();

  if (/franchise|waralaba|kemitraan/.test(subject)) {
    return "Pelajari referensi lanjutan mengenai peluang usaha, model kemitraan, dan strategi bisnis melalui";
  }

  if (/supplier|suplier|distributor|grosir|agen|pemasok|reseller|dropship/.test(subject)) {
    return "Bandingkan pilihan pasokan, kualitas produk, dan mitra distribusi melalui";
  }

  if (/ekspor|impor|perikanan|budidaya/.test(subject)) {
    return "Lengkapi wawasan tentang rantai pasok, perikanan, dan peluang pasar melalui";
  }

  if (/resep|masak|menu|sajian|bumbu|goreng|bakar/.test(subject) || article.category === "Resep masakan") {
    return "Temukan inspirasi olahan dan referensi bahan berkualitas melalui";
  }

  if (/kesehatan|sehat|gizi|protein|kalori|nutrisi|merkuri/.test(subject) || article.category === "Kesehatan") {
    return "Perdalam informasi tentang kualitas bahan pangan, nutrisi, dan keamanan konsumsi melalui";
  }

  if (/seafood|udang|cumi|kerang|kepiting|lobster|tiram/.test(subject)) {
    return "Jelajahi pembahasan seputar seafood, kualitas produk, dan pilihan pasokan melalui";
  }

  if (/ikan|salmon|dori|lele|kakap|tuna|kerapu|patin|nila/.test(subject)) {
    return "Baca referensi tambahan tentang jenis ikan, manfaat, dan produk berkualitas melalui";
  }

  if (/frozen|beku|freezer|nugget|bakso|sosis/.test(subject)) {
    return "Temukan panduan terkait produk frozen food, penyimpanan, dan peluang usaha melalui";
  }

  return "Untuk melengkapi pembahasan ini, baca informasi dan peluang usaha terkait melalui";
}

export function getMeatfishBacklink(
  article: Pick<ArticleRecord, "slug" | "title" | "category">,
): MeatfishBacklink {
  const destination = destinationsByArticleSlug[article.slug] ?? "/produk-meatfish/";
  const topic = summarizeArticleTopic(article.title, article.category);

  return {
    href: "https://meatfish.id" + destination,
    anchor: topic + " di Meatfish.id",
    companionHref: "https://meatfish.co.id" + destination,
    companionAnchor: topic + " di Meatfish.co.id",
    context: getEditorialContext(article),
  };
}
